style.css:
@-moz-document domain("youtube.com"), domain("www.youtube.com") {
/* Background: Lil Peep collage or aesthetic wallpaper */
  body, ytd-app, #content {
    background: url("https://i.imgur.com/Zsmvjg7.jpg") no-repeat center center fixed;
    background-size: cover;
    color: #f1f1f1 !important;
    font-family: 'Space Mono', monospace !important;
  }

  /* Transparent panels */
  #masthead-container,
  #container.ytd-masthead,
  #secondary,
  #primary {
    background-color: rgba(0, 0, 0, 0.7) !important;
    backdrop-filter: blur(5px);
  }

  /* Video titles and text */
  #video-title,
  h1.title,
  #description {
    color: #ffd6e8 !important;
  }

  /* Links and hover accents */
  a, yt-formatted-string.yt-simple-endpoint {
    color: #ff6bcb !important;
  }
  a:hover, yt-formatted-string.yt-simple-endpoint:hover {
    color: #ff3ca2 !important;
  }

  /* Thumbnails highlight border */
  ytd-grid-video-renderer,
  ytd-video-renderer {
    border: 2px solid rgba(255, 107, 203, 0.5) !important;
    border-radius: 8px;
    overflow: hidden;
  }
  ytd-grid-video-renderer:hover,
  ytd-video-renderer:hover {
    border-color: #ff6bcb !important;
  }

  /* Buttons (like thumbs up, menu) */
  yt-icon-button, .yt-spec-button-shape-next {
    color: #f1f1f1 !important;
  }
  yt-icon-button:hover, .yt-spec-button-shape-next:hover {
    background-color: rgba(255, 107, 203, 0.2) !important;
  }

  /* Custom scrollbar */
  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-thumb {
    background-color: #ff6bcb !important;
    border-radius: 4px;
  }
  ::-webkit-scrollbar-track {
    background-color: rgba(0,0,0,0.3) !important;
  }

  /* Comments and video panel background */
  #comments, #comments #contents, #contents.ytd-item-section-renderer {
    background-color: rgba(0,0,0,0.6) !important;
  }

  /* Input search bar styling */
  #search, #search-input input {
    background-color: rgba(255,107,203,0.1) !important;
    color: #fff !important;
    border: 1px solid #ff6bcb !important;
  }
  #search-input input:focus {
    outline: 2px solid #ff6bcb !important;
  }

  /* Footer and end screen */
  ytd-app #footer {
    background-color: rgba(0,0,0,0.8) !important;
    color: #ddd !important;
  }
}
